"""Write a factual report and R input only after the independent audit completes."""
from pathlib import Path
import json,csv
p=Path(__file__).resolve().parent;e=p/'evidence_user_benefit_20261009'
s=json.loads((e/'summary.json').read_bytes());assert s['complete'],'No report of completed benefits before complete independent audit'
rows=s['arms'];lookup={(r['stratum'],r['arm']):r for r in rows}
cap=s['capacity_8k'];demonstrated=cap['bounded_observed_capacity_benefit']
lines=['# Fresh-question user-benefit study, 2026-10-09','','## Completion and scope','',f"All {s['known_model_calls']}/{s['planned_model_calls']} planned calls were independently checked on 24 new graph units. Model: qwen3:1.7b, fixed archived digest; new runtime Ollama0.40.0. Two reader seeds are within-question repeats, not 48 independent questions. This is an extension to the earlier reproduction, not a new run of the original five-trace intervention.",'','## Observed user benefit','']
if demonstrated:
 lines += [f"Under an 8,192-token complete-input serving contract, reversible short labels enabled exact answers in both reader seeds on {len(cap['nonempty_graphs_exact_both_seeds'])}/12 selected capacity graphs with nonempty gold answers. These graph row identities are {cap['nonempty_graphs_exact_both_seeds']}. All12 compact inputs fit; none of their original inputs fit that same contract. This is a demonstrated ability on specific new graph tasks, not a population reliability guarantee."]
else:lines+=['The predefined nonempty exact-in-both-seeds capacity criterion was not met. Source size reduction alone is not counted as a task-solving benefit.']
lines+=['','The original8K reference was never sent with a truncated source and is not scored as zero accuracy. Executed original readers instead used32K context and an8K output allowance; compact capacity readers used8K context and a4K output allowance. Their comparison changes both representation and resource settings and evaluates deployment packages, not an isolated causal compression effect.','','## Complete executed-arm results','','| Stratum | Arm | F1 | EM | Full tokens/answer | Complete wall seconds/answer | Valid/24 | Output-truncated |','|---|---|---:|---:|---:|---:|---:|---:|']
for r in rows:lines.append(f"| {r['stratum']} | {r['arm']} | {r['f1']:.4f} | {r['em']:.4f} | {r['mean_deployment_tokens']:.2f} | {r['mean_deployment_wall_seconds']:.2f} | {r['valid_count']}/24 | {r['length_terminated']} |")
lines+=['','Prefix cost includes the entire single1024-cap source pass plus one reader; it is not divided by the two reader repeats. Preparation CPU time and inverse dictionary storage are separate. Wall times are local observations including runtime behavior, not server-independent speed guarantees.','','## Paired graph-level contrasts','','| Stratum | Contrast | Mean F1 difference | Descriptive95% interval |','|---|---|---:|---|']
for c in s['contrasts']:lines.append(f"| {c['stratum']} | {c['contrast']} | {c['f1_difference']:.4f} | [{c['descriptive_interval'][0]:.4f}, {c['descriptive_interval'][1]:.4f}] |")
lines+=['','The primary short-input comparison is compact-direct minus original-direct. The prefix comparisons are exploratory. An interval crossing zero is not proof of equivalence or improvement. No outcome-driven extension or sample filtering was performed.','','## Does the short trace itself help?','']
for stratum in ['capacity','short']:
 a,b=lookup[stratum,'prefix'],lookup[stratum,'compact'];c=next(x for x in s['contrasts'] if x['stratum']==stratum and x['contrast']=='prefix-compact')
 lines.append(f"- {stratum}: prefix-minus-direct F1={c['f1_difference']:.4f}; full preparation-inclusive token ratio={a['mean_deployment_tokens']/b['mean_deployment_tokens']:.3f}. This must be distinguished from benefits attributable to reversible labels. No placement mechanism is isolated because there is no matched append arm.")
lines+=['','## Evidence and limitations','','Exact raw HTTP bytes, write-ahead payloads and fixed selections are in `logs/user_benefit_20261009`. Independent source-round-trip and rescore evidence is in `paper/evidence_user_benefit_20261009`. A CPU graph oracle is used only to verify labels and score outputs, never to choose mappings or fill model traces. Conventional algorithms can solve these graph tasks directly; this study probes model behavior and does not show that language models are the best production graph solvers. No natural-document transfer, cross-question amortization, energy, monetary or third-party execution benefit is established.','','A favorable user-benefit result should be integrated into the manuscript only with its complete failure counts, resource contract and independent audit. This report alone does not certify arXiv readiness.']
(p/'USER_BENEFIT_RESULTS_20261009.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
with (e/'plot_arms.csv').open('w',newline='',encoding='utf-8') as f:
 w=csv.DictWriter(f,fieldnames=['stratum','arm','f1','em','mean_deployment_tokens','mean_deployment_wall_seconds']);w.writeheader();w.writerows({k:r[k] for k in w.fieldnames} for r in rows)
print('Wrote factual full-denominator benefit report and R input.')
